#include <stdio.h>
#include <stdlib.h>
struct Buffer { size_t length; int *data; };
int main(void) {
 struct Buffer b = {0, NULL};
 b.length = 3;
 b.data = malloc(b.length * sizeof *b.data);
 if (b.data == NULL) return 1;
 for (size_t i=0; i<b.length; ++i) b.data[i] = (int)i;
 printf("%d\n", b.data[2]);
 free(b.data);
 return 0;
}
